const STORAGE_KEY = 'tavern_helper_display_settings_苏北乡村';
const LEGACY_STORAGE_KEYS = [
    'tavern_helper_display_settings_华北乡村',
    'tavern_helper_settings_华北乡村',
];
const SettingsSchema = z
    .object({
    fontSize: z.coerce
        .number()
        .transform(value => _.clamp(Math.round(value), 14, 24))
        .prefault(17),
    lineHeight: z
        .enum(['compact', 'normal', 'relaxed', 'loose'])
        .prefault('normal'),
    fontFamily: z
        .enum(['serif', 'sans', 'kaiti', 'songti'])
        .prefault('serif'),
})
    .prefault({});
function storage() {
    try {
        return window.parent.localStorage;
    }
    catch {
        return window.localStorage;
    }
}
export const useSettingsStore = defineStore('subei-village-settings', () => {
    const saved = (() => {
        try {
            let current = storage().getItem(STORAGE_KEY);
            if (!current) {
                for (const legacyKey of LEGACY_STORAGE_KEYS) {
                    current = storage().getItem(legacyKey);
                    if (current)
                        break;
                }
            }
            const migrated = SettingsSchema.parse(current ? JSON.parse(current) : {});
            if (!storage().getItem(STORAGE_KEY) && current) {
                try {
                    storage().setItem(STORAGE_KEY, JSON.stringify(migrated));
                }
                catch {
                    console.warn('[苏北乡村] 旧显示设置已读取，但暂时无法写入新的独立存储');
                }
            }
            return migrated;
        }
        catch {
            return SettingsSchema.parse({});
        }
    })();
    const fontSize = ref(saved.fontSize);
    const lineHeight = ref(saved.lineHeight);
    const fontFamily = ref(saved.fontFamily);
    watch([fontSize, lineHeight, fontFamily], ([fs, lh, ff]) => {
        try {
            storage().setItem(STORAGE_KEY, JSON.stringify({ fontSize: fs, lineHeight: lh, fontFamily: ff }));
        }
        catch (error) {
            console.warn('[苏北乡村] 显示设置保存失败', error);
            toastr.warning('设置已临时应用，但浏览器拒绝保存');
        }
    }, { immediate: true });
    return { fontSize, lineHeight, fontFamily };
});
