import { Schema } from '../../schema';
import { migrateLegacyState } from '../../stateMigration';
/**
 * 从最新楼层向上回溯读取最近的合法游戏变量状态。
 * 当用户刚发送消息或 AI 正在流式生成时，当前最新楼层（-1）尚未写入 stat_data；
 * 回溯读取可保证前端所有面板（玩家档案、世界时间、角色名册、商店、钱包）在对话流式全周期实时稳定存在，绝不闪烁清空。
 */
export function readLatestValidStatData() {
    try {
        const lastId = getLastMessageId();
        if (lastId >= 0) {
            for (let id = lastId; id >= 0; id--) {
                try {
                    const raw = _.get(Mvu.getMvuData({ type: 'message', message_id: id }), 'stat_data') ??
                        _.get(getVariables({ type: 'message', message_id: id }), 'stat_data');
                    if (!_.isEmpty(raw)) {
                        const parsed = Schema.safeParse(migrateLegacyState(raw));
                        if (parsed.success) {
                            const d = parsed.data;
                            // 只要存在有效玩家或已初始化状态，即为有效的历史真实状态
                            if (d.玩家信息.姓名 || d.系统状态.初始化状态 !== '未开始') {
                                return d;
                            }
                        }
                    }
                }
                catch {
                    // 向上继续查找
                }
            }
        }
        // 尝试读取聊天级变量
        const chatRaw = _.get(getVariables({ type: 'chat' }), 'stat_data');
        if (!_.isEmpty(chatRaw)) {
            const parsed = Schema.safeParse(migrateLegacyState(chatRaw));
            if (parsed.success && (parsed.data.玩家信息.姓名 || parsed.data.系统状态.初始化状态 !== '未开始')) {
                return parsed.data;
            }
        }
    }
    catch (error) {
        console.warn('[苏北乡村] 读取最近有效变量失败', error);
    }
    // 最终兜底默认空状态
    return Schema.parse({});
}
export const useDataStore = defineStore('mvu_data.huabei_village', () => {
    const data = ref(readLatestValidStatData());
    function syncFromRuntime() {
        const next = readLatestValidStatData();
        // 保护机制：如果 next 读到了有效数据，或者当前本身就是空状态，则更新；防止新楼层空对象将已初始化数据冲掉
        const currentIsValid = Boolean(data.value.玩家信息.姓名 || data.value.系统状态.初始化状态 !== '未开始');
        const nextIsValid = Boolean(next.玩家信息.姓名 || next.系统状态.初始化状态 !== '未开始');
        if (nextIsValid || !currentIsValid) {
            if (!_.isEqual(data.value, next)) {
                data.value = next;
            }
        }
    }
    // 周期性同步与酒馆事件联动
    useIntervalFn(syncFromRuntime, 1500);
    if (typeof eventOn === 'function') {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, syncFromRuntime);
        eventOn(tavern_events.MESSAGE_RECEIVED, syncFromRuntime);
        eventOn(tavern_events.MESSAGE_UPDATED, syncFromRuntime);
        eventOn(tavern_events.MESSAGE_EDITED, syncFromRuntime);
        eventOn(tavern_events.MESSAGE_DELETED, syncFromRuntime);
        eventOn(tavern_events.MESSAGE_SWIPED, syncFromRuntime);
        eventOn(tavern_events.GENERATION_ENDED, syncFromRuntime);
    }
    return {
        data,
        syncFromRuntime,
    };
});
